<div class="page-actions"><p class="muted">Kehadiran harian dan ringkasan bulanan pegawai.</p><a class="btn btn-primary" href="<?= site_url('attendance/new') ?>">＋ Catat absensi</a></div>
<form method="get" action="<?= site_url('attendance') ?>" class="filter-bar"><label>Bulan rekap<input type="month" name="month" value="<?= esc($month) ?>"></label><button class="btn btn-plain">Tampilkan</button><a class="btn btn-plain" href="<?= site_url('attendance?month=' . $month) ?>">Muat ulang</a></form>
<div class="summary-grid summary-four"><?php foreach (['hadir' => 'Hadir', 'izin' => 'Izin', 'sakit' => 'Sakit', 'alpa' => 'Alpa'] as $key => $label): ?><div class="summary-card"><span><?= esc($label) ?> <small>catatan</small></span><strong><?= number_format($summary[$key]) ?></strong></div><?php endforeach ?></div>
<div class="panel"><div class="table-wrap"><table><thead><tr><th>TANGGAL</th><th>NAMA PEGAWAI</th><th>STATUS</th><th>JAM MASUK</th><th>JAM PULANG</th><th>CATATAN</th><th></th></tr></thead><tbody><?php foreach ($records as $record): ?><tr><td><?= esc(date('d/m/Y', strtotime($record['attendance_date']))) ?></td><td><span class="strong"><?= esc($record['employee_name']) ?></span><small class="table-sub"><?= esc($record['position']) ?></small></td><td><span class="badge badge-<?= esc($record['status']) ?>"><?= esc(ucfirst($record['status'])) ?></span></td><td><?= esc($record['check_in'] ?: '—') ?></td><td><?= esc($record['check_out'] ?: '—') ?></td><td><?= esc($record['notes'] ?: '—') ?></td><td><form method="post" action="<?= site_url('attendance/' . $record['id'] . '/delete') ?>" onsubmit="return confirm('Hapus catatan absensi ini?')"><?= csrf_field() ?><button class="link-danger">Hapus</button></form></td></tr><?php endforeach ?></tbody></table></div><?php if (! $records): ?><div class="empty-state">Belum ada data absensi pada bulan ini.</div><?php endif ?></div>
